import json,hashlib
p='/workspace/scratch/volume4/batch519-528.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(522,[
('وبالجملة: فالقرآن ـ من أوله إلى آخره ـ يبطل هذا المذهب ويرده، كما تبطله العقول والفطر والحس.', 'В целом Коран от начала до конца опровергает и отвергает это учение, как опровергают его разум, естество и чувственное восприятие.'),
('وقد قال بعض أهل العلم: الالتفات إلى الأسباب شرك في التوحيد، ومحو الأسباب أن تكون أسبابا تعيير في وجه العقل، والإعراض عن الأسباب بالكلية قدح في الشرع. والتوكل معنى يلتئم من معنى التوحيد والعقل والشرع.', 'Один из людей знания сказал: «Обращение к причинам — приобщение сотоварищей в единобожии; устранение причин как причин — оскорбление разума; полное отвращение от причин — посягательство на Закон. Упование — смысл, соединяющий единобожие, разум и Закон».'),
('وهذا الكلام يحتاج إلى شرح وتقييد. فالالتفات إلى الأسباب ضربان: أحدهما شرك، والآخر عبودية وتوحيد. فالشرك: أن يعتمد عليها ويطمئن إليها، ويعتقد أنها محصلة للمقصود بذاتها؛ فهو معرض عن المسبب لها،', 'Эти слова нуждаются в объяснении и уточнении. Обращение к причинам бывает двух видов: один — многобожие, другой — поклонение и единобожие. Многобожие состоит в том, чтобы полагаться на них, находить в них успокоение и считать, что они сами по себе достигают желаемого. Тогда человек отворачивается от Того, Кто создаёт их,')])
page(523,[
('ويجعل نظره والتفاته مقصورا عليها. وأما إن التفت إليها التفات امتثال وقيام بها وأداء لحق العبودية فيها وإنزالها منازلها، فهذا الالتفات عبودية وتوحيد، إذا لم يشغله عن الالتفات إلى المسبب. وأما محوها أن تكون أسبابا، فقدح في العقل والحس والفطر. فإن أعرض عنها بالكلية كان ذلك قدحا في الشرع، وإبطالا له.', 'и ограничивает ими свой взгляд и внимание. Если же он обращается к ним, исполняя повеление, прибегая к ним, выполняя должное в поклонении и отводя им подобающее место, такое обращение — поклонение и единобожие, если оно не отвлекает его от обращения к Создающему причины. Устранение же их как причин посягает на разум, чувственное восприятие и естество. А полное отвращение от них посягает на Закон и упраздняет его.'),
('وحقيقة التوكل: القيام بالأسباب، والاعتماد بالقلب على المسبب، واعتقاد أنها بيده فإن شاء منعها اقتضاءها وإن شاء جعلها مقتضية لضد أحكامها، وإن شاء أقام لها موانع وصوارف تعارض اقتضاءها وتدفعه.', 'Сущность упования — прибегать к причинам, сердцем полагаться на Создающего их и верить, что они в Его руке. Если Он пожелает, то не даст им обусловить свой результат; если пожелает, сделает так, что они обусловят противоположное своим обычным следствиям; если пожелает, установит препятствия и отводящие факторы, которые противодействуют обусловливаемому ими результату и устраняют его.'),
('فالموحد المتوكل لا يلتفت إلى الأسباب، بمعنى أنه لا يطمئن إليها، ولا يرجوها، ولا يخافها، ولا يركن إليها. ويلتفت إليها بمعنى أنه لا يسقطها، ولا يهملها ويلغيها، بل يكون قائما بها، ملتفتا إليها، ناظرا إلى مسببها ومجريها.', 'Единобожник, уповающий на Аллаха, не обращается к причинам в том смысле, что не находит в них успокоения, не надеется на них, не боится их и не опирается на них. Он обращается к ним в том смысле, что не отвергает их, не пренебрегает ими и не упраздняет их, а прибегает к ним, уделяет им внимание, взирая на Того, Кто создаёт их и приводит в действие.'),
('فلا يصح التوكل عقلا وشرعا إلا عليه وحده سبحانه، فإنه ليس في الوجود سبب تام موجب إلا مشيئته وحده، فهو الذي سبب الأسباب، وجعل فيها القوى والاقتضاء لآثارها، ولم يجعل منها سببا يقتضي وحده أثره، بل لا بد معه من سبب آخر يشاركه، وجعل لها أسبابا تضادها وتمانعها؛ بخلاف مشيئته سبحانه، فإنها لا تحتاج إلى أمر آخر، ولا في الأسباب الحادثة ما يبطلها ويضادها. وإن كان سبحانه قد يبطل حكم مشيئته بمشيئته، فيشاء الأمر ثم يشاء ما يضاده ويمنع حصوله، والجميع بمشيئته واختياره. فلا يصح', 'И по разуму, и по Закону верно уповать лишь на Него одного, Пречистого. В бытии нет совершенной причины, необходимо влекущей результат, кроме одной лишь Его воли. Он создал причины и вложил в них силы и способность обусловливать их следствия. Ни одну из них Он не сделал причиной, которая одна обусловливала бы своё следствие: вместе с нею непременно нужна другая, участвующая с ней. Он также создал причины, противодействующие им и препятствующие их действию. Его же воля, напротив, не нуждается ни в чём другом, и среди возникших причин нет того, что могло бы её отменить и ей воспротивиться. При этом Пречистый может отменить действие Своей воли Своей же волей: пожелать одно, а затем пожелать противоположное и воспрепятствовать его осуществлению. Всё это — по Его воле и выбору. Поэтому недопустимо')])
page(524,[
('التوكل إلا عليه، ولا الالتجاء إلا إليه، ولا الخوف إلا منه، ولا الرجاء إلا له، ولا الطمع إلا في رحمته؛ كما قال أعرف الخلق به: «أعوذ برضاك من سخطك، وأعوذ بمعافاتك من عقوبتك، وأعوذ بك منك». وقال: «لا ملجأ ولا منجى منك إلا إليك».', 'уповать иначе как на Него, искать убежища иначе как у Него, бояться иначе как Его, надеяться иначе как на Него и желать иначе как Его милости. Как сказал лучше всех творений познавший Его: «Прибегаю к Твоему довольству от Твоего гнева, прибегаю к Твоему избавлению от Твоего наказания и прибегаю к Тебе от Тебя». И он сказал: «Нет убежища и спасения от Тебя, кроме как у Тебя».'),
('فإذا جمعت بين هذا التوحيد وبين إثبات الأسباب استقام قلبك على السير إلى الله، ووضح لك الطريق الأعظم الذي مضى عليه جميع رسل الله وأنبيائه وأتباعهم، وهو الصراط المستقيم، صراط الذين أنعم الله عليهم. وبالله التوفيق.', 'Если ты соединишь это единобожие с утверждением причин, твоё сердце выпрямится на пути к Аллаху и тебе станет ясен великий путь, по которому прошли все посланники Аллаха, Его пророки и их последователи. Это прямой путь — путь тех, кого Аллах облагодетельствовал. Аллах дарует содействие.'),
('وما سبق به حكمه وعلمه حق، وهو لا ينافي إثبات الأسباب، ولا يقتضي إسقاطها، فإنه سبحانه قد علم وحكم أن كذا وكذا يحدث بسبب كذا وكذا، فسبق العلم والحكم بحصوله عن سببه، فإسقاط السبب خلاف موجب علمه وحكمه. فمن نظر إلى الحدوث بغير الأسباب لم يكن نظره وشهوده مطابقا للحق؛ بل كان شهوده غيبة، ونظره عمى. فإذا كان علمه وحكمه قد سبق بحدوث الأشياء بأسبابها، فكيف يشهد العبد الأمور بخلاف ما هي عليه في علمه وحكمه وخلقه وأمره؟', 'То, что предшествует в Его решении и знании, — истина; оно не противоречит утверждению причин и не требует их отвержения. Пречистый знал и решил, что такое-то произойдёт по такой-то причине: знание и решение о возникновении результата из его причины предшествовали ему. Отвержение причины противоречит необходимому следствию Его знания и решения. Рассмотрение и созерцание того, кто смотрит на возникновение вещей без причин, не соответствуют истине: его созерцание — отсутствие, а взгляд — слепота. Если Его знание и решение предшествовали возникновению вещей посредством их причин, как же раб может созерцать дела вопреки тому, каковы они в Его знании, решении, творении и повелении?'),
('والعلل التي تنفى وتتقى في الأسباب نوعان. أحدهما: الاعتماد عليها، والتوكل عليها، والثقة بها، ورجاؤها وخوفها. فهذا شرك يرق ويغلظ وبين', 'Изъяны, которые следует устранять и которых следует остерегаться в отношении причин, бывают двух видов. Первый — полагаться на них, уповать на них, доверять им, надеяться на них и бояться их. Это многобожие, которое бывает тоньше, грубее и между')])
page(525,[
('ذلك. الثاني: ترك ما أمر به من الأسباب، وهذا أيضا قد يكون كفرا وظلما وبين ذلك.', 'этими крайностями. Второй — оставлять предписанные причины; это также может быть неверием, несправедливостью и промежуточным между ними.'),
('بل على العبد أن يفعل ما أمر به من الأسباب، ويتوكل عليه توكل من يعتقد أن الأمر كله بمشيئة الله، سبق به علمه وحكمه، وأن السبب لا يضر ولا ينفع، ولا يعطي ولا يمنع، ولا يقضي ولا يحكم، ولا يحصل للعبد ما لم تسبق به المشيئة الإلهية، ولا يصرف عنه ما سبق به الحكم والعلم. فيأتي بالأسباب إتيان من لا يرى النجاة والفلاح والوصول إلا بها، ويتوكل على الله توكل من يرى أنها لا تنجيه، ولا تحصل له فلاحا، ولا توصله إلى المقصود. فيجرد عزمه للقيام بها حرصا واجتهادا، ويفرغ قلبه من الاعتماد عليها والركون إليها تجريدا للتوكل، واعتمادا على الله وحده.', 'Раб обязан прибегать к предписанным причинам и уповать на Него упованием того, кто убеждён: всё совершается по воле Аллаха, согласно предшествующим знанию и решению. Причина не вредит и не приносит пользы, не даёт и не удерживает, не выносит решения и не судит; раб не получит того, чему не предшествовала божественная воля, и от него не будет отведено то, чему предшествовали решение и знание. Он прибегает к причинам так, как прибегает тот, кто видит спасение, преуспеяние и достижение лишь через них, и уповает на Аллаха так, как уповает тот, кто считает: они не спасают его, не дают ему преуспеяния и не приводят к желаемому. Он с усердием и старанием всецело направляет решимость на применение причин и освобождает сердце от надежды на них и опоры на них, очищая упование и полагаясь на одного Аллаха.'),
('وقد جمع النبي صلى الله عليه وسلم بين هذين الأصلين في الحديث الصحيح، حيث يقول: «احرص على ما ينفعك، واستعن بالله، ولا تعجز». فأمره بالحرص على الأسباب، والاستعانة بالمسبب. ونهاه عن العجز؛ وهو نوعان: تقصيره في الأسباب وعدم الحرص عليها، وتقصيره في الاستعانة بالله وترك تجريدها. فالدين كله ـ ظاهره وباطنه، شرائعه وحقائقه ـ تحت هذه الكلمات النبوية.', 'Пророк, да благословит его Аллах и приветствует, соединил обе основы в достоверном хадисе: «Стремись к тому, что приносит тебе пользу, проси помощи у Аллаха и не проявляй бессилия». Он повелел усердно прибегать к причинам и просить помощи у Создающего их. Он запретил бессилие, которое бывает двух видов: небрежность в отношении причин и отсутствие усердия в их применении, а также небрежность в просьбе о помощи у Аллаха и отказ посвящать её одному Ему. Вся религия — её внешнее и внутреннее, её установления и реальности — заключена в этих пророческих словах.'),
('فصل', 'Раздел'),
('قوله: «والصعود عن منازعات العقول». هذا حق، ولا يتم التوحيد ولا', 'Его слова «и возвышение над пререканиями разумов» верны. Единобожие и')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
